const SERVICE_IDS = {
  PSRI: 1287, Baxter: 489, Nihon: 338, ONDC: 2023,
  Infres: 741, VMM: 295, ResMed: 1702, LOTS: 805,
  Facility: [741, 295, 338]
};

const q = items[0].json.query || {};
const processName = q.process;
const rawServiceId = SERVICE_IDS[processName];
if (!rawServiceId) throw new Error(`Unknown or missing process: ${processName}`);
const serviceIdCond = Array.isArray(rawServiceId) ? `IN (${rawServiceId.join(',')})` : `= ${rawServiceId}`;
const from = q.from;
const to = q.to;
if (!from || !to) throw new Error('Missing from/to date params');

// Both branches below normalize ResMed's raw activity_tracker spellings
// ('Admin'/'Sagarika' -> 'Sagarika Bose', 'Gulshan' -> 'Gulshan Khan',
// 'Avijit' -> 'Avijit Dey') the same way combined_summary_daily_job's
// Step9 does, so this live feed lines up with the agent names the
// dashboard already shows. Each branch groups twice (raw name, then
// normalized name) so two raw spellings that collapse onto the same
// canonical name never produce two rows for one agent.
const query = `
SELECT 'appreciation' AS metric_type, process_name, agent_name, NULL AS category, NULL AS score, SUM(value) AS value, SUM(cnt) AS cnt
FROM (
  SELECT dp.process_name,
    CASE
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) IN ('Admin','Sagarika') THEN 'Sagarika Bose'
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) = 'Gulshan' THEN 'Gulshan Khan'
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) = 'Avijit' THEN 'Avijit Dey'
      ELSE TRIM(at.agent_name)
    END COLLATE utf8mb4_unicode_ci AS agent_name,
    SUM(COALESCE(at.count,1)) AS value, COUNT(*) AS cnt
  FROM calls.activity_tracker at
  JOIN calls.dim_process dp ON dp.service_id = at.service_id
  WHERE at.service_id ${serviceIdCond} AND at.type = 'Appreciation'
    AND (at.final_status IS NULL OR at.final_status <> 'No')
    AND at.report_date BETWEEN '${from}' AND '${to}'
  GROUP BY TRIM(at.agent_name), dp.process_name
) raw_appr
GROUP BY process_name, agent_name

UNION ALL

SELECT 'escalation' AS metric_type, process_name, agent_name, NULL AS category, NULL AS score, SUM(value) AS value, SUM(cnt) AS cnt
FROM (
  SELECT dp.process_name,
    CASE
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) IN ('Admin','Sagarika') THEN 'Sagarika Bose'
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) = 'Gulshan' THEN 'Gulshan Khan'
      WHEN at.service_id = 1702 AND TRIM(at.agent_name) = 'Avijit' THEN 'Avijit Dey'
      ELSE TRIM(at.agent_name)
    END COLLATE utf8mb4_unicode_ci AS agent_name,
    SUM(COALESCE(at.count,1)) AS value, COUNT(*) AS cnt
  FROM calls.activity_tracker at
  JOIN calls.dim_process dp ON dp.service_id = at.service_id
  WHERE at.service_id ${serviceIdCond} AND at.type = 'Escalation'
    AND at.report_date BETWEEN '${from}' AND '${to}'
  GROUP BY TRIM(at.agent_name), dp.process_name
) raw_esc
GROUP BY process_name, agent_name;
`;

return [{ json: { query } }];
